1	//===- MapElementwiseExpansion.cpp - Pre-processing for map_elementwise ---===//
2	//
3	// Implements pre-processing utilities for tt.map_elementwise:
4	//   - Scalar-level if-conversion (scf.if → arith.select)
5	//   - Tensor-level expansion (lift scalar ops to tensor ops)
6	//   - K-way pack support via recursive binary split/join
7	//
8	// Expansion approach (tensor lifting):
9	//
10	//   All map_elementwise ops are expanded before dialect conversion. The scalar
11	//   region body is lifted to tensor-level ops: each scalar op becomes its
12	//   tensor equivalent, constants are splatted via tt.splat, and scf.if is
13	//   replaced with arith.select on tensors. The map_elementwise op is then
14	//   erased, leaving only standard tensor ops that flow through the normal
15	//   TritonToTileIR conversion pipeline.
16	//
17	//   For regions with control flow (scf.if), the lifting handles branch
18	//   flattening (scf.if → arith.select) as part of the tensor expansion.
19	//   For pack > 1, inputs are split into sub-element tensors via recursive
20	//   binary tt.split, processed independently, then reassembled via tt.join.
21	//
22	//===----------------------------------------------------------------------===//
23	
24	#include "MapElementwiseExpansion.h"
25	
26	#include "mlir/Dialect/Arith/IR/Arith.h"
27	#include "mlir/Dialect/SCF/IR/SCF.h"
28	#include "mlir/IR/IRMapping.h"
29	#include "triton/Dialect/Triton/IR/Dialect.h"
30	
31	namespace mlir {
32	namespace triton {
33	namespace {
34	
35	using namespace mlir;
36	
37	//===----------------------------------------------------------------------===//
38	// Tensor lifting utilities
39	//===----------------------------------------------------------------------===//
40	
41	// Forward declaration for mutual recursion.
42	static LogicalResult liftBodyOp(
43	    Operation &bodyOp, OpBuilder &builder, Location loc,
44	    IRMapping &mapping, ArrayRef<int64_t> shape, Attribute encoding);
45	
46	// Lift a scalar value to tensor: if already tensor, return as-is.
47	// If scalar (e.g., hoisted constant or block argument from outside),
48	// insert tt.splat to broadcast to the target tensor shape.
49	static Value liftToTensor(
50	    Value val, OpBuilder &builder, Location loc, IRMapping &mapping,
51	    ArrayRef<int64_t> shape, Attribute encoding) {
52	  Value mapped = mapping.lookupOrDefault(val);
53	  if (isa<RankedTensorType>(mapped.getType()))
54	    return mapped;
55	  auto tensorType = RankedTensorType::get(shape, mapped.getType(), encoding);
56	  auto splat = triton::SplatOp::create(builder, loc, tensorType, mapped);
57	  mapped = splat.getResult();
58	  mapping.map(val, mapped);
59	  return mapped;
60	}
61	
62	// Recursively lift all ops in a region body (single block) to tensor level.
63	// Returns the lifted values corresponding to the scf.yield operands.
64	static SmallVector<Value> liftRegionBody(
65	    Region &region, OpBuilder &builder, Location loc,
66	    IRMapping &mapping, ArrayRef<int64_t> shape, Attribute encoding) {
67	  assert(region.hasOneBlock() && "expected single-block region");
68	  Block &body = region.front();
69	  for (auto &op : body.without_terminator()) {
70	    if (failed(liftBodyOp(op, builder, loc, mapping, shape, encoding)))
71	      return {};
72	  }
73	  // Collect yield operands
74	  auto yieldOp = cast<scf::YieldOp>(body.getTerminator());
75	  SmallVector<Value> results;
76	  for (auto val : yieldOp.getOperands())
77	    results.push_back(
78	        liftToTensor(val, builder, loc, mapping, shape, encoding));
79	  return results;
80	}
81	
82	// Lift a single scalar op to its tensor-level equivalent.
83	// Handles:
84	//   - arith::ConstantOp → DenseElementsAttr splat
85	//   - scf::IfOp → recursive expansion into arith.select
86	//   - generic ops → remap operands to tensor, create new op with tensor types
87	static LogicalResult liftBodyOp(
88	    Operation &bodyOp, OpBuilder &builder, Location loc,
89	    IRMapping &mapping, ArrayRef<int64_t> shape, Attribute encoding) {
90	
91	  // Skip terminators handled by callers
92	  if (isa<triton::MapElementwiseReturnOp, scf::YieldOp>(&bodyOp))
93	    return success();
94	
95	  // (1) arith::ConstantOp → DenseElementsAttr splat
96	  if (auto constOp = dyn_cast<arith::ConstantOp>(&bodyOp)) {
97	    auto scalarAttr = cast<TypedAttr>(constOp.getValue());
98	    auto tensorType = RankedTensorType::get(
99	        shape, scalarAttr.getType(), encoding);
100	    auto splatAttr = DenseElementsAttr::get(tensorType, scalarAttr);
101	    auto newConst = arith::ConstantOp::create(builder, loc, splatAttr);
102	    mapping.map(constOp.getResult(), newConst.getResult());
103	    return success();
104	  }
105	
106	  // (2) scf::IfOp → lift both branches, emit arith.select
107	  if (auto ifOp = dyn_cast<scf::IfOp>(&bodyOp)) {
108	    Value condTensor =
109	        liftToTensor(ifOp.getCondition(), builder, loc, mapping, shape,
110	                     encoding);
111	
112	    // Process then region
113	    IRMapping thenMapping(mapping);
114	    SmallVector<Value> thenVals =
115	        liftRegionBody(ifOp.getThenRegion(), builder, loc, thenMapping,
116	                       shape, encoding);
117	    if (thenVals.empty() && ifOp.getNumResults() > 0)
118	      return failure();
119	
120	    // Process else region
121	    IRMapping elseMapping(mapping);
122	    SmallVector<Value> elseVals =
123	        liftRegionBody(ifOp.getElseRegion(), builder, loc, elseMapping,
124	                       shape, encoding);
125	    if (elseVals.empty() && ifOp.getNumResults() > 0)
126	      return failure();
127	
128	    // Emit arith.select for each result
129	    for (auto [i, oldRes] : llvm::enumerate(ifOp.getResults())) {
130	      auto sel = arith::SelectOp::create(
131	          builder, loc, condTensor, thenVals[i], elseVals[i]);
132	      mapping.map(oldRes, sel.getResult());
133	    }
134	    return success();
135	  }
136	
137	  // (3) Generic op: remap operands to tensor, fix result types
138	  SmallVector<Value> newOperands;
139	  for (auto operand : bodyOp.getOperands()) {
140	    newOperands.push_back(
141	        liftToTensor(operand, builder, loc, mapping, shape, encoding));
142	  }
143	
144	  SmallVector<Type> newResultTypes;
145	  for (auto result : bodyOp.getResults()) {
146	    newResultTypes.push_back(
147	        RankedTensorType::get(shape, result.getType(), encoding));
148	  }
149	
150	  OperationState state(loc, bodyOp.getName());
151	  state.addOperands(newOperands);
152	  state.addTypes(newResultTypes);
153	  state.addAttributes(bodyOp.getAttrs());
154	  auto *newOp = Operation::create(state);
155	  builder.insert(newOp);
156	
157	  for (auto [oldRes, newRes] :
158	       llvm::zip(bodyOp.getResults(), newOp->getResults())) {
159	    mapping.map(oldRes, newRes);
160	  }
161	  return success();
162	}
163	
164	//===----------------------------------------------------------------------===//
165	// Scalar-level if-conversion (used by ifConvertMapElementwiseRegions)
166	//===----------------------------------------------------------------------===//
167	
168	// Convert all scf.if → arith.select within a region.
169	// Uses walk + reverse to process innermost scf.if first, ensuring outer
170	// scf.if bodies are already pure when we process them.
171	static LogicalResult scalarIfConvert(Region &region) {
172	  if (!region.hasOneBlock())
173	    return failure();
174	  Block &body = region.front();
175	
176	  // Collect all scf.if ops (including nested ones in then/else regions)
177	  SmallVector<scf::IfOp> ifOps;
178	  body.walk([&](scf::IfOp ifOp) { ifOps.push_back(ifOp); });
179	
180	  // Process innermost first (walk visits outer before inner, reverse fixes this)
181	  for (auto ifOp : llvm::reverse(ifOps)) {
182	    OpBuilder builder(ifOp);
183	    Location loc = ifOp.getLoc();
184	
185	    // Get then yield values
186	    auto &thenBlock = ifOp.getThenRegion().front();
187	    auto thenYield = cast<scf::YieldOp>(thenBlock.getTerminator());
188	    SmallVector<Value> thenVals(thenYield.getOperands());
189	
190	    // Get else yield values
191	    auto &elseBlock = ifOp.getElseRegion().front();
192	    auto elseYield = cast<scf::YieldOp>(elseBlock.getTerminator());
193	    SmallVector<Value> elseVals(elseYield.getOperands());
194	
195	    // Move then/else ops before the scf.if (they're pure, safe to speculate)
196	    for (auto &op : llvm::make_early_inc_range(thenBlock.without_terminator()))
197	      op.moveBefore(ifOp);
198	    for (auto &op : llvm::make_early_inc_range(elseBlock.without_terminator()))
199	      op.moveBefore(ifOp);
200	
201	    // Create arith.select for each result
202	    SmallVector<Value> selectResults;
203	    for (auto [tv, ev] : llvm::zip(thenVals, elseVals)) {
204	      auto sel = arith::SelectOp::create(
205	          builder, loc, ifOp.getCondition(), tv, ev);
206	      selectResults.push_back(sel.getResult());
207	    }
208	
209	    // Replace scf.if results with selects and erase
210	    ifOp.replaceAllUsesWith(selectResults);
211	    ifOp.erase();
212	  }
213	
214	  return success();
215	}
216	
217	//===----------------------------------------------------------------------===//
218	// K-way pack support via recursive binary split/join
219	//===----------------------------------------------------------------------===//
220	
221	// Recursively split a tensor along its last dimension using binary tt.split.
222	// Input: tensor of shape [.., M, K] where K is a power of 2.
223	// Output: K tensors of shape [.., M].
224	// For K=1: just return the input (no split needed).
225	// For K=2: one tt.split → 2 results.
226	// For K>2: split into halves, recurse on each half.
227	static SmallVector<Value> recursiveSplit(
228	    OpBuilder &builder, Location loc, Value tensor, int K) {
229	  if (K == 1) {
230	    // Last dim is 1, drop it via reshape
231	    auto srcType = cast<RankedTensorType>(tensor.getType());
232	    auto srcShape = srcType.getShape();
233	    SmallVector<int64_t> newShape(srcShape.begin(), srcShape.end() - 1);
234	    auto newType = RankedTensorType::get(
235	        newShape, srcType.getElementType(), srcType.getEncoding());
236	    Value reshaped = triton::ReshapeOp::create(
237	        builder, loc, newType, tensor).getResult();
238	    return {reshaped};
239	  }
240	
241	  if (K == 2) {
242	    // Base case: binary split
243	    auto splitOp = triton::SplitOp::create(builder, loc, tensor);
244	    return {splitOp.getOutLHS(), splitOp.getOutRHS()};
245	  }
246	
247	  // Recursive case: reshape last dim K → [K/2, 2], split, recurse
248	  auto srcType = cast<RankedTensorType>(tensor.getType());
249	  auto srcShape = srcType.getShape();
250	  // [.., M, K] → [.., M, K/2, 2]
251	  SmallVector<int64_t> reshapedShape(srcShape.begin(), srcShape.end());
252	  reshapedShape.back() = K / 2;
253	  reshapedShape.push_back(2);
254	
255	  auto reshapedType = RankedTensorType::get(
256	      reshapedShape, srcType.getElementType(), srcType.getEncoding());
257	  Value reshaped = triton::ReshapeOp::create(
258	      builder, loc, reshapedType, tensor).getResult();
259	
260	  // Split [.., M, K/2, 2] → lhs: [.., M, K/2], rhs: [.., M, K/2]
261	  auto splitOp = triton::SplitOp::create(builder, loc, reshaped);
262	
263	  // Recurse on each half
264	  SmallVector<Value> lhsResults = recursiveSplit(builder, loc, splitOp.getOutLHS(), K / 2);
265	  SmallVector<Value> rhsResults = recursiveSplit(builder, loc, splitOp.getOutRHS(), K / 2);
266	
267	  // Interleave: [lhs0, rhs0, lhs1, rhs1, ...] to maintain element order
268	  SmallVector<Value> results;
269	  for (unsigned i = 0; i < lhsResults.size(); i++) {
270	    results.push_back(lhsResults[i]);
271	    results.push_back(rhsResults[i]);
272	  }
273	  return results;
274	}
275	
276	// Recursively join K tensors into one using binary tt.join.
277	// Input: K tensors of shape [.., M].
278	// Output: tensor of shape [.., M, K].
279	// Reverses the recursiveSplit operation.
280	static Value recursiveJoin(
281	    OpBuilder &builder, Location loc, ArrayRef<Value> tensors, int K,
282	    RankedTensorType finalType) {
283	  if (K == 1) {
284	    // Add back last dim via reshape: [.., M] → [.., M, 1]
285	    auto srcType = cast<RankedTensorType>(tensors[0].getType());
286	    auto srcShape = srcType.getShape();
287	    SmallVector<int64_t> newShape(srcShape.begin(), srcShape.end());
288	    newShape.push_back(1);
289	    auto newType = RankedTensorType::get(
290	        newShape, srcType.getElementType(), srcType.getEncoding());
291	    return triton::ReshapeOp::create(builder, loc, newType, tensors[0]).getResult();
292	  }
293	
294	  if (K == 2) {
295	    // Base case: binary join
296	    return triton::JoinOp::create(builder, loc, tensors[0], tensors[1]).getResult();
297	  }
298	
299	  // Recursive case: de-interleave into even/odd halves, recurse, join
300	  SmallVector<Value> lhsTensors, rhsTensors;
301	  for (unsigned i = 0; i < tensors.size(); i += 2) {
302	    lhsTensors.push_back(tensors[i]);
303	    rhsTensors.push_back(tensors[i + 1]);
304	  }
305	
306	  // Recurse on halves → each produces [.., M, K/2]
307	  Value lhs = recursiveJoin(builder, loc, lhsTensors, K / 2, finalType);
308	  Value rhs = recursiveJoin(builder, loc, rhsTensors, K / 2, finalType);
309	
310	  // Reshape each [.., M, K/2] → [.., M * K/2] to prepare for join
311	  // Then join [.., M*K/2] + [.., M*K/2] → [.., M*K/2, 2]
312	  // Then reshape [.., M*K/2, 2] → [.., M, K]
313	
314	  // Actually simpler: join adds a new last dim of 2.
315	  // [.., M, K/2] join → [.., M, K/2, 2]
316	  // Then reshape [.., M, K/2, 2] → [.., M, K]
317	  auto joined = triton::JoinOp::create(builder, loc, lhs, rhs);
318	
319	  // Reshape to collapse the last two dims
320	  auto joinedType = cast<RankedTensorType>(joined.getResult().getType());
321	  auto joinedShape = joinedType.getShape();
322	  SmallVector<int64_t> collapsedShape(joinedShape.begin(), joinedShape.end() - 2);
323	  collapsedShape.push_back(joinedShape[joinedShape.size() - 2] * 2);
324	
325	  auto collapsedType = RankedTensorType::get(
326	      collapsedShape, joinedType.getElementType(), joinedType.getEncoding());
327	  return triton::ReshapeOp::create(builder, loc, collapsedType, joined.getResult()).getResult();
328	}
329	
330	//===----------------------------------------------------------------------===//
331	// Main expansion logic
332	//===----------------------------------------------------------------------===//
333	
334	static bool regionHasScfIf(Region &region) {
335	  bool found = false;
336	  region.walk([&](scf::IfOp) { found = true; return WalkResult::interrupt(); });
337	  return found;
338	}
339	
340	static LogicalResult expandMapElementwiseOpsImpl(Operation *rootOp) {
341	  SmallVector<triton::MapElementwiseOp> opsToExpand;
342	  rootOp->walk([&](triton::MapElementwiseOp op) {
343	    opsToExpand.push_back(op);
344	  });
345	
346	  for (auto op : opsToExpand) {
347	    auto &region = op.getScalarOp();
348	
349	    if (!region.hasOneBlock()) {
350	      op.emitError("map_elementwise region has multiple blocks; "
351	                   "expected lift-tt-cf-to-scf to have run first");
352	      return failure();
353	    }
354	
355	    int pack = op.getPack();
356	    if (!llvm::isPowerOf2_32(pack)) {
357	      op.emitError("pack must be a power of 2");
358	      return failure();
359	    }
360	
361	    Block &body = region.front();
362	    OpBuilder builder(op);
363	    Location loc = op.getLoc();
364	    unsigned numSrcs = op.getSrcs().size();
365	
366	    auto inputType = cast<RankedTensorType>(op.getSrcs()[0].getType());
367	    auto origShape = inputType.getShape();
368	    auto encoding = inputType.getEncoding();
369	
370	    if (pack == 1) {
371	      // Direct lifting on original tensor shape.
372	      IRMapping mapping;
373	      for (auto [arg, src] : llvm::zip(body.getArguments(), op.getSrcs()))
374	        mapping.map(arg, src);
375	
376	      for (auto &bodyOp : body.without_terminator()) {
377	        if (failed(liftBodyOp(bodyOp, builder, loc, mapping, origShape,
378	                              encoding)))
379	          return failure();
380	      }
381	
382	      auto terminator =
383	          cast<triton::MapElementwiseReturnOp>(body.getTerminator());
384	      SmallVector<Value> results;
385	      for (auto val : terminator.getResult())
386	        results.push_back(
387	            liftToTensor(val, builder, loc, mapping, origShape, encoding));
388	
389	      op.replaceAllUsesWith(results);
390	      op.erase();
391	    } else {
392	      // pack > 1: Decompose into sub-element tensors, lift, then reassemble.
393	      //
394	      // Block arg order: repeatInterleave([src0_type, src1_type, ...], pack)
395	      //   = [src0_e0, src0_e1, ..., src0_eK-1, src1_e0, ...]
396	      // Return order: repeatInterleave([out0_type, out1_type, ...], pack)
397	      //   = [out0_e0, out0_e1, ..., out0_eK-1, out1_e0, ...]
398	
399	      int64_t lastDim = origShape.back();
400	      if (lastDim % pack != 0) {
401	        op.emitError("last dimension not divisible by pack");
402	        return failure();
403	      }
404	
405	      // Step 1: Reshape each input [.., N] → [.., N/K, K]
406	      // Step 2: Recursively split into K sub-tensors of shape [.., N/K]
407	      SmallVector<SmallVector<Value>> splitResults(numSrcs);
408	      for (unsigned i = 0; i < numSrcs; i++) {
409	        Value src = op.getSrcs()[i];
410	        auto srcType = cast<RankedTensorType>(src.getType());
411	
412	        // Build reshaped shape: [.., N/K, K]
413	        SmallVector<int64_t> reshapedShape(srcType.getShape().begin(),
414	                                           srcType.getShape().end());
415	        reshapedShape.back() = lastDim / pack;
416	        reshapedShape.push_back(pack);
417	
418	        auto reshapedType = RankedTensorType::get(
419	            reshapedShape, srcType.getElementType(), srcType.getEncoding());
420	        Value reshaped = triton::ReshapeOp::create(
421	            builder, loc, reshapedType, src).getResult();
422	
423	        // Recursively split into K sub-tensors
424	        splitResults[i] = recursiveSplit(builder, loc, reshaped, pack);
425	      }
426	
427	      // Compute the sub-tensor shape (used for lifting)
428	      SmallVector<int64_t> subShape(origShape.begin(), origShape.end());
429	      subShape.back() = lastDim / pack;
430	
431	      // Infer sub-tensor encoding from the split result
432	      auto subEncoding =
433	          cast<RankedTensorType>(splitResults[0][0].getType()).getEncoding();
434	
435	      // Step 3: Map block args to sub-tensors.
436	      // Block args are interleaved: [src0_e0, src0_e1, ..., src1_e0, ...]
437	      IRMapping mapping;
438	      unsigned argIdx = 0;
439	      for (unsigned srcIdx = 0; srcIdx < numSrcs; srcIdx++) {
440	        for (int p = 0; p < pack; p++) {
441	          mapping.map(body.getArgument(argIdx++), splitResults[srcIdx][p]);
442	        }
443	      }
444	
445	      // Step 4: Lift all body ops on the sub-tensor shape [.., N/K]
446	      for (auto &bodyOp : body.without_terminator()) {
447	        if (failed(liftBodyOp(bodyOp, builder, loc, mapping, subShape,
448	                              subEncoding)))
449	          return failure();
450	      }
451	
452	      // Step 5+6: Collect results, join K sub-tensors, reshape back.
453	      auto terminator =
454	          cast<triton::MapElementwiseReturnOp>(body.getTerminator());
455	      auto retVals = terminator.getResult();
456	      unsigned numOutputs = op.getNumResults();
457	
458	      SmallVector<Value> results;
459	      for (unsigned outIdx = 0; outIdx < numOutputs; outIdx++) {
460	        // Collect the K sub-element results for this output
461	        SmallVector<Value> subResults;
462	        for (int p = 0; p < pack; p++) {
463	          subResults.push_back(
464	              liftToTensor(retVals[outIdx * pack + p], builder, loc, mapping,
465	                           subShape, subEncoding));
466	        }
467	
468	        // Join K sub-tensors → [.., N/K, K]
469	        auto outputType = cast<RankedTensorType>(op->getResult(outIdx).getType());
470	        Value joined = recursiveJoin(builder, loc, subResults, pack, outputType);
471	
472	        // Reshape [.., N/K, K] → [.., N]
473	        Value result = triton::ReshapeOp::create(
474	            builder, loc, outputType, joined).getResult();
475	        results.push_back(result);
476	      }
477	
478	      op.replaceAllUsesWith(results);
479	      op.erase();
480	    }
481	  }
482	
483	  return success();
484	}
485	
486	} // anonymous namespace
487	
488	//===----------------------------------------------------------------------===//
489	// Public API
490	//===----------------------------------------------------------------------===//
491	
492	LogicalResult ifConvertMapElementwiseRegions(Operation *rootOp) {
493	  WalkResult result = rootOp->walk([&](triton::MapElementwiseOp op) {
494	    if (failed(scalarIfConvert(op.getScalarOp())))
495	      return WalkResult::interrupt();
496	    return WalkResult::advance();
497	  });
498	  return failure(result.wasInterrupted());
499	}
500	
501	LogicalResult expandMapElementwiseOps(Operation *rootOp) {
502	  return expandMapElementwiseOpsImpl(rootOp);
503	}
504	
505	} // namespace triton
506	} // namespace mlir
